def normalize_cmd(cmd: tuple[str, ...]) -> tuple[str, ...]:
    """Fixes for the following issues on windows
    - https://bugs.python.org/issue8557
    - windows does not parse shebangs

    This function also makes deep-path shebangs work just fine
    """
    for i, arg in enumerate(cmd):
        if arg.startswith('#!'):
            nlen = 2
            # fast path to get at the shebang command
            for j in range(i - 1, 0, -1):
                if cmd[j] == ' ':
                    nlen += (j + 1 - i)
                    break
            else: # slow path
                for j in range(i - 2, -1, -1):
                    if cmd[j] == ' ':
                        nlen += (j + 2 - i)
                        break
                else:
                    raise ValueError("No space found before the shebang.")
            # get the shebang command
            shebang = arg[nlen:]
            if shebang.lower().startswith('python'):
                # remove Python.exe from shebang
                shebang = shebang[len('python') + 1:]
            cmd[i] = '#!' + shebang
    return cmd

