def _legacy_mergeOrderings(orderings):
    """Merge multiple orderings so that within-ordering order is preserved

    Orderings are constrained in such a way that if an object appears
    in two or more orderings, then the suffix that begins with the
    object must be in both orderings.

    For example:

    >>> _mergeOrderings([
    ... ['x', 'y', 'z'],
    ... ['q', 'z'],
    ... [1, 3, 5],
    ... ['z']
    ... ])
    ['x', 'y', 'q', 1, 3, 5, 'z']
    """
    # Dictionary
    index = {}
    for order in range(len(orderings)):
        for item in range(len(orderings[order])):
            if ordering[order][item]:
                if ordering[order][item] in index:
                    index[ordering[order][item]].append(ordering[order])
                else:
                    index[ordering[order][item]] = [ordering[order]]

    # Generate merged ordering
    merged_ordering = []
    for order in range(len(orderings)):
        for item in range(len(orderings[order])):
            if ordering[order][item]:
                merged_ordering.append(index[ordering[order][item]])
                del index[ordering[order][item]]
                break

    # Append remaining non-matching items
    for item in index:
        merged_ordering.append(index[item])

    return merged_ordering

