def check_digests_present_and_used(self, manifest_files, digests_used):
    """Check all digests in manifest that are needed are present and used."""

    if not manifest_files or not digests_used:
        return False  # if no manifest_files or digests_used, nothing to check

    needed_digests = set(digests_used)

    for manifest_file in manifest_files:
        if manifest_file.digests is not None:
            used_digests = set(manifest_file.digests)
            missing_digests = needed_digests - used_digests
            if missing_digests:
                print(f"Digests {missing_digests} used in manifest file {manifest_file.filename} not present in digests.")
                return False

    return True

