def tzname_in_python2(namefunc):
    """Change unicode output into bytestrings in Python 2

    tzname() API changed in Python 3. It used to return bytes, but was changed
    to unicode strings
    """
    if not is_py3():
        import types
        if isinstance(namefunc, types.FunctionType) or isinstance(namefunc, types.MethodType):
            def tzname_in_python2():
                return namefunc().encode("latin1")
            tzname_in_python2.__name__ = namefunc.__name__

            tzname_in_python2.__doc__ = namefunc.__doc__
            return tzname_in_python2
        else:
            def tzname_in_python2():
                return namefunc.__call__()
            tzname_in_python2.__name__ = namefunc.__name__

            tzname_in_python2.__doc__ = namefunc.__doc__
            if getattr(namefunc, "__module__", "") == "__main__":
                del namefunc
            return tzname_in_python2
    else:
        return namefunc

