def validate_version_inventories(self, version_dirs):
    """
    Each version SHOULD have an inventory up to that point.

    Also keep a record of any content digests different from those in the root inventory
    so that we can also check them when validating the content.

    version_dirs is an array of version directory names and is assumed to be in
    version sequence (1, 2, 3...).
    """
    root_inventory = self.find_inventories()[0]  # Assume the root inventory is always the first one
    content_digests = {}

    for i, version_dir in enumerate(version_dirs):
        # Find inventory for the current version
        current_inventory = self.find_inventories(version_dir)

        # Validate that there is an inventory for the current version
        if not current_inventory:
            raise RuntimeError(f"Version {version_dir} does not have an inventory.")

        # Check content digests for the current version
        for file_path, digest in current_inventory.iter_content_digests():
            if file_path in content_digests:
                if digest != content_digests[file_path]:
                    raise ValueError(f"Content digest for file {file_path} in version {version_dir} is different from the root version. Current: {digest}, Root: {content_digests[file_path]}.")
            else:
                content_digests[file_path] = digest

        # Mark the version as validated
        self.mark_version_validated(version_dir)

