def find_roots(graph, prop, roots=None):
    """
    Find the roots in some sort of transitive hierarchy.

    find_roots(graph, rdflib.RDFS.subClassOf)
    will return a set of all roots of the sub-class hierarchy

    Assumes triple of the form (child, prop, parent), i.e. the direction of
    RDFS.subClassOf or SKOS.broader

    """
    if roots is None:
        roots = set()

    if prop == rdflib.RDFS.subClassOf:
        # find all classes that are not subclasses of any other classes
        for child in graph.subjects(predicate=rdflib.RDFS.subClassOf):
            if not any(graph.predecessors(child) for parent in graph.subjects(predicate=rdflib.RDFS.subClassOf)):
                roots.add(child)
    elif prop == rdflib.SKOS.broader:
        # find all concepts that are not broader than any other concepts
        for child in graph.subjects(predicate=rdflib.SKOS.broader):
            if not any(graph.predecessors(child) for parent in graph.subjects(predicate=rdflib.SKOS.broader)):
                roots.add(child)
    else:
        raise ValueError("Unknown property")

    return roots

