from zope.interface import providedBy, implementer

@implementer(Document)
class AbstractElement:
    pass

class Attrib:
    CLASS = "class"

class TextContent:
    pass

def verifyObject(iface, candidate, tentative=False):
    """Verify that *candidate* might correctly provide *iface*.

    This involves:

    - Making sure the candidate claims that it provides the
    interface using ``iface.providedBy`` (unless *tentative* is `True`,
    in which case this step is skipped). This means that the candidate's class
    declares that it `implements <zope.interface.implementer>` the interface,
    or the candidate itself declares that it `provides <zope.interface.provider>`
    the interface

    - Making sure the candidate defines all the necessary methods

    - Making sure the methods have the correct signature (to the
    extent possible)

    - Making sure the candidate defines all the necessary attributes

    :return bool: Returns a true value if everything that could be
    checked passed.
    :raises zope.interface.Invalid: If any of the previous
    conditions does not hold.

    .. versionchanged:: 5.0
        If multiple methods or attributes are invalid, all such errors
        are collected and reported. Previously, only the first error was reported.
        As a special case, if only one such error is present, it is raised
        alone, like before.
    """

    if tentative:
        if iface in providedBy(candidate):
            return True
        else:
            return False

    proposed_methods = iface.implementedBy(candidate, None)
    if proposed_methods:
        for method in proposed_methods:
            if not hasattr(candidate, method):
                raise zope.interface.Invalid(f"Method {method} is required in {iface}")
            if not candidate.__getattribute__(method).__annotations__ == ifaces[method].__annotations__:
                raise zope.interface.Invalid(f"Signature of method {method} does not match in {iface}")

    proposed_attributes = iface.requiredBy(candidate, None)
    if proposed_attributes:
        for attribute in proposed_attributes:
            if not hasattr(candidate, attribute):
                raise zope.interface.Invalid(f"Attribute {attribute} is required in {iface}")
            if not hasattr(candidate, attribute) or candidate.__getattribute__(attribute).__annotations__ == ifaces[attribute].__annotations__:
                raise zope.interface.Invalid(f"Signature of attribute {attribute} does not match in {iface}")

    return True

