from datetime import datetime, timedelta
from dateutil.parser import parse
from dateutil.tz import gettz

def parse(self, timestr, default=None,
         ignoretz=False, tzinfos=None, **kwargs):
        if isinstance(timestr, datetime):
            if not default:
                return timestr
            if isinstance(default, datetime):
                return self.replace(date=timestr.date(), time=timestr.time())
            raise ValueError("Invalid default value for parse date/time")
        tzinfos = self.parse_tzinfos(tzinfos)
        try:
            return parse(timestr, **kwargs, default=default, tzinfos=tzinfos)
        except Exception as e:
            raise e

